interface.definition:
#"SYSTEM_SYSRULES_headerContentLayout"(
  contents: {
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {},
          showWhen: #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP", "DESKTOP_WIDE" })
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_sectionLayout_v1"(
              label: "Detalles",
              contents: {
                #"SYSTEM_SYSRULES_cardLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Código",
                      value: {
                        a!defaultValue(
                                  ri!TipoCategoriaEtiqueta[#"urn:appian:record-field:v1:f3ec0006-548d-4ea9-9537-802665e19cd8/65cdf38a-d02f-4338-9220-f48cf237f719"],
                                  "–"
                                )
                      }
                    )
                  },
                  padding: "STANDARD",
                  shape: "SEMI_ROUNDED"
                )
              },
              marginBelow: "MORE",
              labelSize: "MEDIUM",
              labelColor: "STANDARD"
            )
          },
          width: "WIDE"
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_sectionLayout_v1"(
              label: "Acciones",
              contents: {
                #"SYSTEM_SYSRULES_recordActionField_v1"(
                  actions: {
                    #"SYSTEM_SYSRULES_recordActionItem"(
                      action: #"urn:appian:record-action:v1:f3ec0006-548d-4ea9-9537-802665e19cd8/a0ccd35b-d013-4235-8e26-67e2e38bb878",
                      identifier: ri!TipoCategoriaEtiqueta[#"urn:appian:record-field:v1:f3ec0006-548d-4ea9-9537-802665e19cd8/a69c1350-1df3-4697-a268-6090ff54020f"]
                    ),
                    #"SYSTEM_SYSRULES_recordActionItem"(
                      action: #"urn:appian:record-action:v1:f3ec0006-548d-4ea9-9537-802665e19cd8/86721db2-7118-4662-bbed-ff506560bcb5",
                      identifier: ri!TipoCategoriaEtiqueta[#"urn:appian:record-field:v1:f3ec0006-548d-4ea9-9537-802665e19cd8/a69c1350-1df3-4697-a268-6090ff54020f"]
                    )
                  },
                  align: "CENTER",
                  style: "SIDEBAR_PRIMARY",
                  display: "LABEL_AND_ICON"
                )
              },
              marginBelow: "MORE",
              labelSize: "MEDIUM",
              labelColor: "STANDARD"
            )
          },
          width: "MEDIUM"
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {},
          showWhen: #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP", "DESKTOP_WIDE" })
        )
      },
      stackWhen: {
        "TABLET_PORTRAIT",
        "PHONE"
      },
      marginAbove: if(
        #"SYSTEM_SYSRULES_isNativeMobile"(),
        "NONE",
        if(
          #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP", "DESKTOP_WIDE" }),
          "MORE",
          "STANDARD"
        )
      ),
      spacing: "SPARSE"
    )
  },
  backgroundColor: "#fbfbfb"
)

a:ruleInputTestConfigs.a:value:
